package com.yuri.music;
import android.app.*;import android.net.Uri;import android.view.*;import android.webkit.*;import androidx.webkit.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
final class SpotifyHost{
 final Activity activity;WebView web;Dialog dialog;int sequence;final ConcurrentHashMap<Integer,CompletableFuture<JSONObject>> pending=new ConcurrentHashMap<>();
 SpotifyHost(Activity activity){this.activity=activity;}
 static boolean allowed(String text){Uri uri=Uri.parse(text);return "https".equals(uri.getScheme())&&Arrays.asList("open.spotify.com","accounts.spotify.com").contains(uri.getHost());}
 JSONObject handle(JSONObject request)throws Exception{String action=request.getString("op").substring(8);if(action.equals("open")){CompletableFuture<JSONObject> opened=new CompletableFuture<>();activity.runOnUiThread(()->{try{open();opened.complete(new JSONObject().put("ok",true));}catch(Exception e){opened.completeExceptionally(e);}});return opened.get(15,TimeUnit.SECONDS);}if(web==null){if(action.equals("status"))return new JSONObject().put("connected",false).put("message","Conecte sua conta Spotify.");throw new IOException("Clique em Conectar Spotify.");}if(action.equals("logout")){activity.runOnUiThread(()->web.loadUrl("https://accounts.spotify.com/logout"));return new JSONObject().put("ok",true);}JSONObject data=new JSONObject(request.toString());data.remove("requestId");data.remove("op");data.put("action",action);int id=++sequence;CompletableFuture<JSONObject> response=new CompletableFuture<>();pending.put(id,response);String script="(async()=>{let value;try{value=window.NoctuneSpotify?await window.NoctuneSpotify.run("+data+"):{error:'Aguarde o Spotify carregar e entre na sua conta.'};}catch(e){value={error:'O Spotify não respondeu.'};}window.NoctuneSpotifyHost.postMessage(JSON.stringify({id:"+id+",value}));})()";activity.runOnUiThread(()->{if(web!=null)web.evaluateJavascript(script,null);});try{return response.get(25,TimeUnit.SECONDS);}finally{pending.remove(id);}}
 void open()throws Exception{if(dialog!=null){dialog.show();return;}dialog=new Dialog(activity);dialog.setTitle("Conectar Spotify · Nocturne");web=new WebView(activity);web.setBackgroundColor(0xff000000);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setMediaPlaybackRequiresUserGesture(false);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptThirdPartyCookies(web,true);String bridge;try(InputStream stream=activity.getAssets().open("spotify-page.js")){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=stream.read(buffer))>0)bytes.write(buffer,0,n);bridge=new String(bytes.toByteArray(),StandardCharsets.UTF_8);}final String code=bridge;
 WebViewCompat.addWebMessageListener(web,"NoctuneSpotifyHost",Collections.singleton("https://open.spotify.com"),(view,message,origin,mainFrame,reply)->{if(!mainFrame||!"https://open.spotify.com".equals(origin.toString()))return;try{JSONObject result=new JSONObject(message.getData());CompletableFuture<JSONObject> future=pending.get(result.getInt("id"));if(future!=null)future.complete(result.getJSONObject("value"));}catch(Exception ignored){}});
 web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){return !allowed(request.getUrl().toString());}@Override public void onPageFinished(WebView view,String url){if("open.spotify.com".equals(Uri.parse(url).getHost())&&url.startsWith("https://"))view.evaluateJavascript(code,null);}});
 web.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(PermissionRequest request){if(!"https://open.spotify.com".equals(request.getOrigin().toString())){request.deny();return;}List<String> grant=new ArrayList<>();for(String resource:request.getResources())if(resource.equals(PermissionRequest.RESOURCE_PROTECTED_MEDIA_ID))grant.add(resource);if(grant.isEmpty())request.deny();else request.grant(grant.toArray(new String[0]));}});
 dialog.setContentView(web);dialog.show();if(dialog.getWindow()!=null)dialog.getWindow().setLayout(WindowManager.LayoutParams.MATCH_PARENT,WindowManager.LayoutParams.MATCH_PARENT);web.loadUrl("https://open.spotify.com/");}
 void dispose(){for(CompletableFuture<JSONObject> f:pending.values())f.cancel(true);pending.clear();if(dialog!=null)dialog.dismiss();if(web!=null)web.destroy();web=null;dialog=null;}
}
